// loader.ts
import type { DataArgs } from "@kasperrt/smolter/react";

export async function clientLoader({ request, signal }: DataArgs) {
  const query = new URL(request.url).searchParams.get("q") ?? "";
  const response = await fetch(`/api/tasks?q=${encodeURIComponent(query)}`, { signal });

  return response.json();
}

