import type { DataArgs } from "@kasperrt/smolter/react";

export async function action({ request, params }: DataArgs) {
  const body = await request.formData();

  return updateTask(params.id, String(body.get("title")));
}

import type { ClientLoaderArgs } from "@kasperrt/smolter/react";

export async function clientLoader({ serverLoader }: ClientLoaderArgs) {
  const serverData = await serverLoader();

  return { serverData, online: navigator.onLine };
}
